    26→import { ExoPlayerBoundary } from './ExoPlayerBoundary';
    27→import { Ionicons } from '@expo/vector-icons';
    28→import { useMedia, StatusItem, SavedItem } from '@/contexts/MediaContext';
    29→import { useThemeColors } from '@/contexts/ThemeContext';
    30→import { useThumbnail } from '@/hooks/media/useThumbnail';
    31→import { createStyles, SW, SH } from './viewerStyles';
    32→
    33→const VIEWER_PLACEHOLDER = { blurhash: 'L6PZfSi_.AyE_3t7t7R**0o#DgR4' };
    34→
    35→export interface ViewerItemProps {
    36→  item: StatusItem | SavedItem;
    37→  isActive: boolean;
    38→  isNearActive: boolean;
    39→  onToggleControls: () => void;
    40→  showControls: boolean;
    41→  controlsOpacity: Animated.Value;
    42→}
    43→
    44→// Module-level flag — set to true either at load time (UIManager check in
    45→// isAvailable() returns false) or on the first ExoPlayerBoundary catch.
    46→// Once true it stays true for the whole app session so ExoPlayerView is
    47→// never rendered again and the "View config not found" error never fires.
    48→//
    49→// Evaluated once at module load — isAvailable() is synchronous.
    50→let exoPlayerModuleUnavailable = !exoPlayerIsAvailable();
    51→
    52→export function ViewerItem({
    53→  item,
    54→  isActive,
    55→  isNearActive,
    56→  onToggleControls,
    57→}: ViewerItemProps) {
    58→  const COLORS = useThemeColors();
    59→  const styles = useMemo(() => createStyles(COLORS), [COLORS]);
    60→  const { prepareStatusForViewing } = useMedia();
    61→
    62→  const cachedThumb = useThumbnail(item.id);
    63→
    64→  const [displayUri, setDisplayUri] = useState<string | null>(null);
    65→  const [videoError, setVideoError] = useState<string | null>(null);
    66→  // Initialises from the module-level flag so subsequent items instantly go to
    67→  // the expo-video fallback without ever trying to render ExoPlayerView again.
    68→  const [nativePlayerFailed, setNativePlayerFailed] = useState(exoPlayerModuleUnavailable);
    69→
    70→  // Thumbnail fades from 1 (fully visible) to 0 (hidden) once video plays.
    71→  // Using Animated.Value so the fade is smooth and never flickers.
    72→  const thumbnailOpacity = useRef(new Animated.Value(1)).current;
    73→  const isVideoPlayingRef = useRef(false);
    74→
    75→  const prepareCancelRef = useRef(false);
    76→
    77→  const initialSource = useMemo(() => {
    78→    return 'localUri' in item ? (item as SavedItem).localUri : item.uri;
    79→  }, [item.id]); // eslint-disable-line react-hooks/exhaustive-deps
    80→
    81→  const isSAF = initialSource.startsWith('content://');
    82→
    83→  // ── Reset everything when item changes ──────────────────────────────────
    84→  useEffect(() => {
    85→    prepareCancelRef.current = true;
    86→    setDisplayUri(null);
    87→    setVideoError(null);
    88→    // nativePlayerFailed is NOT reset here — ExoPlayer availability is a device-level
    89→    // fact for this build. Once the module-level flag is set, all subsequent items
    90→    // initialise directly to the expo-video fallback (see useState initialiser above).
    91→    thumbnailOpacity.setValue(1);
    92→    isVideoPlayingRef.current = false;
    93→    prepareCancelRef.current = false;
    94→  }, [item.id]); // eslint-disable-line react-hooks/exhaustive-deps
    95→
    96→  // Re-show thumbnail when slide becomes inactive (for next swipe-back)
    97→  useEffect(() => {
    98→    if (item.type !== 'video') return;
    99→    if (!isActive) {
   100→      thumbnailOpacity.setValue(1);
   101→      isVideoPlayingRef.current = false;
   102→    }
   103→  }, [isActive, item.type]); // eslint-disable-line react-hooks/exhaustive-deps
   104→
   105→  // ── Prepare URI ──────────────────────────────────────────────────────────
   106→  useEffect(() => {
   107→    if (!isNearActive) {
   108→      if (!isActive) {
   109→        setDisplayUri(null);
   110→        setVideoError(null);
   111→      }
   112→      return;
   113→    }
   114→
   115→    if (displayUri) return;
   116→
   117→    if (item.type === 'image') {
   118→      setDisplayUri(initialSource);
   119→      return;
   120→    }
   121→
   122→    if (!isActive) return;
   123→
   124→    if (!isSAF) {
   125→      console.log(
   126→        '[ViewerItem] displayUri set (non-SAF) uri_type=' +
   127→          (initialSource.startsWith('file://') ? 'FILE' : initialSource.startsWith('content://') ? 'CONTENT⚠️' : 'OTHER⚠️'),
   128→      );
   129→      setDisplayUri(initialSource);
   130→      return;
   131→    }
   132→
   133→    prepareCancelRef.current = false;
   134→    setVideoError(null);
   135→
   136→    prepareStatusForViewing(item as StatusItem, { forPlayback: true })
   137→      .then((fileUri) => {
   138→        if (prepareCancelRef.current) return;
   139→        if (fileUri) {
   140→          console.log(
   141→            '[ViewerItem] displayUri set (SAF copy) uri_type=' +
   142→              (fileUri.startsWith('file://') ? 'FILE' : fileUri.startsWith('content://') ? 'CONTENT⚠️' : 'OTHER⚠️') +
   143→              ' uri=' + fileUri.slice(0, 100),
   144→          );
   145→          setDisplayUri(fileUri);
   146→        } else {
   147→          setVideoError('Could not load video — tap to retry');
   148→        }
   149→      })
   150→      .catch(() => {
   151→        if (prepareCancelRef.current) return;
   152→        setVideoError('Could not load video — tap to retry');
   153→      });
   154→
   155→    return () => { prepareCancelRef.current = true; };
   156→  }, [initialSource, isSAF, item, isNearActive, isActive, displayUri, prepareStatusForViewing]); // eslint-disable-line react-hooks/exhaustive-deps
   157→
   158→  // ── Callbacks for VideoPlayerView ────────────────────────────────────────
   159→  const handlePlaying = useCallback(() => {
   160→    if (isVideoPlayingRef.current) return;
   161→    isVideoPlayingRef.current = true;
   162→    Animated.timing(thumbnailOpacity, {
   163→      toValue: 0,
   164→      duration: 180,
   165→      useNativeDriver: true,
   166→    }).start();
   167→  }, [thumbnailOpacity]);
   168→
   169→  const handleError = useCallback((_msg: string) => {
   170→    setVideoError('Tap to retry');
   171→  }, []);
   172→
   173→  // Called by ExoPlayerBoundary when the native view throws at render time,
