   178→    exoPlayerModuleUnavailable = true;
   179→    setNativePlayerFailed(true);
   180→  }, []);
   181→
   182→  const handleRetry = useCallback(() => {
   183→    setVideoError(null);
   184→    setDisplayUri(null);
   185→    thumbnailOpacity.setValue(1);
   186→    isVideoPlayingRef.current = false;
   187→  }, [thumbnailOpacity]);
   188→
   189→  const mediaUri = displayUri || initialSource;
   190→
   191→  // ── Pinch-to-zoom for images ───────────────────────────────────────────
   192→  const imageScale = useSharedValue(1);
   193→  const savedScale = useSharedValue(1);
   194→  const translateX = useSharedValue(0);
   195→  const translateY = useSharedValue(0);
   196→  const savedTranslateX = useSharedValue(0);
   197→  const savedTranslateY = useSharedValue(0);
   198→
   199→  useEffect(() => {
   200→    imageScale.value = 1;
   201→    savedScale.value = 1;
   202→    translateX.value = 0;
   203→    translateY.value = 0;
   204→    savedTranslateX.value = 0;
   205→    savedTranslateY.value = 0;
   206→  }, [item.id, isActive]); // eslint-disable-line react-hooks/exhaustive-deps
   207→
   208→  const pinchGesture = Gesture.Pinch()
   209→    .onUpdate((e) => {
   210→      imageScale.value = Math.min(Math.max(savedScale.value * e.scale, 1), 6);
   211→    })
   212→    .onEnd(() => {
   213→      if (imageScale.value < 1.15) {
   214→        imageScale.value = withSpring(1);
   215→        translateX.value = withSpring(0);
   216→        translateY.value = withSpring(0);
   217→        savedScale.value = 1;
   218→        savedTranslateX.value = 0;
   219→        savedTranslateY.value = 0;
   220→      } else {
   221→        savedScale.value = imageScale.value;
   222→        const maxX = ((imageScale.value - 1) * SW) / 2;
   223→        const maxY = ((imageScale.value - 1) * SW) / 2;
   224→        if (Math.abs(translateX.value) > maxX) {
   225→          const cx = translateX.value > 0 ? maxX : -maxX;
   226→          translateX.value = withSpring(cx);
   227→          savedTranslateX.value = cx;
   228→        }
   229→        if (Math.abs(translateY.value) > maxY) {
   230→          const cy = translateY.value > 0 ? maxY : -maxY;
   231→          translateY.value = withSpring(cy);
   232→          savedTranslateY.value = cy;
   233→        }
   234→      }
   235→    });
   236→
   237→  const panGesture = Gesture.Pan()
   238→    .manualActivation(true)
   239→    .onTouchesMove((_e, state) => {
   240→      if (imageScale.value > 1) state.activate();
   241→      else state.fail();
   242→    })
   243→    .onUpdate((e) => {
   244→      const scale = imageScale.value;
   245→      const maxX = ((scale - 1) * SW) / 2;
   246→      const maxY = ((scale - 1) * SW) / 2;
   247→      const newX = savedTranslateX.value + e.translationX * 0.72;
   248→      const newY = savedTranslateY.value + e.translationY * 0.72;
   249→      translateX.value = Math.max(-maxX, Math.min(maxX, newX));
   250→      translateY.value = Math.max(-maxY, Math.min(maxY, newY));
   251→    })
   252→    .onEnd((e) => {
   253→      const scale = imageScale.value;
   254→      const maxX = ((scale - 1) * SW) / 2;
   255→      const maxY = ((scale - 1) * SW) / 2;
   256→      translateX.value = withDecay(
   257→        { velocity: e.velocityX * 0.5, deceleration: 0.92, clamp: [-maxX, maxX] },
   258→        () => { savedTranslateX.value = translateX.value; },
   259→      );
   260→      translateY.value = withDecay(
   261→        { velocity: e.velocityY * 0.5, deceleration: 0.92, clamp: [-maxY, maxY] },
   262→        () => { savedTranslateY.value = translateY.value; },
   263→      );
   264→    });
   265→
   266→  const doubleTapGesture = Gesture.Tap()
   267→    .numberOfTaps(2)
   268→    .maxDuration(200)
   269→    .onEnd((e) => {
   270→      if (imageScale.value > 1) {
   271→        imageScale.value = withSpring(1);
   272→        translateX.value = withSpring(0);
   273→        translateY.value = withSpring(0);
   274→        savedScale.value = 1;
   275→        savedTranslateX.value = 0;
   276→        savedTranslateY.value = 0;
   277→      } else {
   278→        const target = 2.5;
   279→        imageScale.value = withSpring(target);
   280→        savedScale.value = target;
   281→        const maxX = ((target - 1) * SW) / 2;
   282→        const maxY = ((target - 1) * SW) / 2;
   283→        const tapX = Math.max(-maxX, Math.min(maxX, (SW / 2 - e.x) * (target - 1)));
   284→        const tapY = Math.max(-maxY, Math.min(maxY, (SH / 2 - e.y) * (target - 1)));
   285→        translateX.value = withSpring(tapX);
   286→        translateY.value = withSpring(tapY);
   287→        savedTranslateX.value = tapX;
   288→        savedTranslateY.value = tapY;
   289→      }
   290→    });
   291→
   292→  const singleTapGesture = Gesture.Tap()
   293→    .numberOfTaps(1)
   294→    .onEnd(() => { runOnJS(onToggleControls)(); });
   295→
   296→  const imageGesture = Gesture.Simultaneous(
   297→    pinchGesture,
   298→    panGesture,
   299→    Gesture.Exclusive(doubleTapGesture, singleTapGesture),
   300→  );
   301→
   302→  const imageAnimatedStyle = useAnimatedStyle(() => ({
   303→    transform: [
   304→      { scale: imageScale.value },
   305→      { translateX: translateX.value },
   306→      { translateY: translateY.value },
   307→    ],
   308→  }));
   309→
   310→  return (
   311→    <View style={styles.itemContainer}>
   312→      {item.type === 'image' ? (
   313→        <GestureDetector gesture={imageGesture}>
   314→          <Reanimated.View style={[StyleSheet.absoluteFill, imageAnimatedStyle]}>
   315→            <Image
   316→              source={{ uri: mediaUri }}
   317→              style={styles.image}
   318→              contentFit="contain"
   319→              cachePolicy="memory-disk"
   320→              transition={150}
   321→              priority={isActive ? 'high' : 'low'}
   322→              recyclingKey={item.id}
   323→              allowDownscaling
   324→              decodeFormat="rgb"
   325→              placeholder={VIEWER_PLACEHOLDER}
   326→              placeholderContentFit="cover"
   327→            />
   328→          </Reanimated.View>
   329→        </GestureDetector>
   330→      ) : (
   331→        <View style={StyleSheet.absoluteFill}>
   332→          <View style={styles.videoWrap}>
   333→
   334→            {/* Video player — mounts as soon as displayUri is ready.
   335→                key={displayUri} ensures a fresh player for each new file:// URI.
   336→
   337→                PRIMARY: native ExoPlayerView (TextureView — immune to OEM surface bugs).
   338→                FALLBACK: expo-video VideoPlayerView, used when native module was not
   339→                compiled into the build (ExoPlayerBoundary catches the render error and
   340→                sets nativePlayerFailed=true). */}
   341→            {isActive && displayUri && !nativePlayerFailed && (
   342→              <ExoPlayerBoundary onError={handleNativePlayerFail}>
   343→                <ExoPlayerView
   344→                  key={displayUri}
   345→                  style={StyleSheet.absoluteFill}
   346→                  fileUri={displayUri}
   347→                  paused={false}
   348→                  muted={false}
   349→                  onPlayerReady={handlePlaying}
   350→                  onPlayerError={handleError}
   351→                />
   352→              </ExoPlayerBoundary>
   353→            )}
   354→
   355→            {isActive && displayUri && nativePlayerFailed && (
   356→              <VideoPlayerView
   357→                key={displayUri}
   358→                fileUri={displayUri}
   359→                isActive={isActive}
   360→                onPlaying={handlePlaying}
   361→                onError={handleError}
   362→              />
   363→            )}
   364→
   365→            {/* Thumbnail poster — always behind the video, fades to 0 once
   366→                playingChange fires. Never shows a spinner or play button.
   367→                Opacity animates smoothly: 1 (covering) → 0 (transparent). */}
   368→            <Animated.View
   369→              style={[StyleSheet.absoluteFill, { opacity: thumbnailOpacity }]}
   370→              pointerEvents="none"
   371→            >
   372→              <Image
   373→                source={cachedThumb ? { uri: cachedThumb } : null}
   374→                style={StyleSheet.absoluteFill}
   375→                contentFit="contain"
   376→                cachePolicy="memory-disk"
   377→                transition={0}
   378→                recyclingKey={item.id}
   379→                placeholder={VIEWER_PLACEHOLDER}
   380→                placeholderContentFit="cover"
   381→              />
   382→            </Animated.View>
   383→
   384→            {/* Retry overlay — only shown on actual playback error */}
   385→            {videoError && (
   386→              <TouchableOpacity
   387→                style={[
   388→                  StyleSheet.absoluteFill,
   389→                  {
   390→                    justifyContent: 'center',
   391→                    alignItems: 'center',
   392→                    backgroundColor: 'rgba(0,0,0,0.65)',
   393→                  },
   394→                ]}
   395→                onPress={handleRetry}
   396→                activeOpacity={0.8}
   397→              >
   398→                <Ionicons name="refresh-circle-outline" size={52} color="#fff" />
   399→                <Text style={{ color: '#fff', marginTop: 10, fontSize: 14 }}>
   400→                  Tap to retry
   401→                </Text>
   402→              </TouchableOpacity>
   403→            )}
   404→          </View>
   405→        </View>
   406→      )}
   407→    </View>
   408→  );
