Here's the result of running `cat -n` on a snippet of components/viewer/VideoPlayerView.tsx
     1→/**
     2→ * VideoPlayerView — expo-video player for a single viewer slide.
     3→ *
     4→ * ── WHY THIS COMPONENT EXISTS ────────────────────────────────────────────────
     5→ * key={displayUri} in the parent forces a completely fresh player (and fresh
     6→ * useVideoPlayer hook) for every new file:// URI.  That avoids stale-player
     7→ * state across slides.
     8→ *
     9→ * ── PLAYBACK STRATEGY ────────────────────────────────────────────────────────
    10→ * p.play() inside useVideoPlayer sets ExoPlayer's playWhenReady=true before
    11→ * the surface attaches.  ExoPlayer holds that flag and starts automatically
    12→ * the moment the SurfaceTexture is ready — no external nudge needed.
    13→ *
    14→ * Previous versions added recovery timers and nudge schedules that called
    15→ * player.play() repeatedly after mount.  Those extra calls interrupted
    16→ * ExoPlayer's internal buffer-fill pipeline, causing the play→freeze→play
    17→ * loop on Android 11+.  Removing them lets ExoPlayer manage its own startup
    18→ * and buffering without JS interference.
    19→ *
    20→ * ── THUMBNAIL FADE ───────────────────────────────────────────────────────────
    21→ * timeUpdate fires every 250 ms ONLY when frames are actually advancing to the
    22→ * screen (currentTime > 0).  That is the signal we use to fade the poster
    23→ * thumbnail out.  It is more reliable than playingChange because it confirms
    24→ * real rendering, not just an internal ExoPlayer state flip.
    25→ *
    26→ * ── SWIPE-BACK ───────────────────────────────────────────────────────────────
    27→ * When isActive flips false→true the parent has already reset thumbnailOpacity
    28→ * to 1, so we reset hasCalledOnPlaying so onPlaying() can fire again and fade
    29→ * the thumbnail back out.
    30→ */
    31→import React, { useEffect, useRef, useCallback } from 'react';
    32→import { StyleSheet } from 'react-native';
    33→import { VideoView, useVideoPlayer } from 'expo-video';
    34→
    35→interface VideoPlayerViewProps {
    36→  fileUri: string;
    37→  isActive: boolean;
    38→  onPlaying: () => void;
    39→  onError: (message: string) => void;
    40→}
    41→
    42→// ── Mount counter (module-level) ──────────────────────────────────────────────
    43→// Tracks how many VideoPlayerView instances are alive at once.
    44→// Should always be 1 (the active slide). If you see 2+ the FlatList window
    45→// is mounting too many players simultaneously — that competes for the hardware
    46→// decoder and causes freezes.
    47→let _mountedCount = 0;
    48→
    49→export function VideoPlayerView({
    50→  fileUri,
    51→  isActive,
    52→  onPlaying,
    53→  onError,
    54→}: VideoPlayerViewProps) {
    55→  const isActiveRef = useRef(isActive);
    56→  isActiveRef.current = isActive;
    57→
    58→  const hasCalledOnPlaying = useRef(false);
    59→
    60→  // ── URI diagnostic log ────────────────────────────────────────────────────
    61→  const uriType = fileUri.startsWith('file://')
    62→    ? 'FILE'
    63→    : fileUri.startsWith('content://')
    64→    ? 'CONTENT⚠️'
    65→    : 'OTHER⚠️';
    66→  console.log('[VideoPlayer] URI type=' + uriType + ' uri=' + fileUri.slice(0, 100));
    67→
    68→  const player = useVideoPlayer({ uri: fileUri }, (p) => {
    69→    p.loop = true;
    70→    p.muted = false;
    71→    // timeUpdate fires every 250 ms only when frames are advancing.
    72→    p.timeUpdateEventInterval = 0.25;
    73→    // Sets playWhenReady=true — ExoPlayer starts as soon as the surface
    74→    // attaches.  No further play() calls are needed from JS.
    75→    p.play();
    76→  });
    77→
    78→  const confirmPlaying = useCallback(() => {
    79→    if (hasCalledOnPlaying.current) return;
    80→    hasCalledOnPlaying.current = true;
    81→    onPlaying();
    82→  }, [onPlaying]);
    83→
    84→  useEffect(() => {
    85→    // ── Mount log ─────────────────────────────────────────────────────────
    86→    _mountedCount++;
    87→    console.log('[VideoPlayer] MOUNTED totalActive=' + _mountedCount + (
    88→      _mountedCount > 1 ? ' ⚠️ MULTIPLE PLAYERS' : ''
    89→    ));
    90→
    91→    const timeUpdateSub = player.addListener('timeUpdate', (event: any) => {
    92→      if ((event.currentTime ?? 0) > 0) confirmPlaying();
    93→    });
    94→
    95→    const statusSub = player.addListener('statusChange', (event: any) => {
    96→      // Log every status change so buffering stalls are visible in logcat.
    97→      console.log(
    98→        '[VideoPlayer] statusChange status=' + event.status +
    99→        ' currentTime=' + (player.currentTime?.toFixed(2) ?? '?') +
   100→        ' buffered=' + (player.bufferedPosition?.toFixed(2) ?? '?'),
   101→      );
   102→      if (event.status === 'error') {
   103→        onError(event.error?.message ?? 'Playback error');
   104→      }
   105→    });
   106→
   107→    const playingSub = player.addListener('playingChange', (event: any) => {
   108→      // This log catches play→pause→play loops triggered by external code.
   109→      // If you see rapid alternating true/false here WITHOUT user interaction
   110→      // that is the recovery-loop root cause.
   111→      console.log(
   112→        '[VideoPlayer] playingChange isPlaying=' + event.isPlaying +
   113→        ' currentTime=' + (player.currentTime?.toFixed(2) ?? '?'),
   114→      );
   115→    });
   116→
   117→    return () => {
   118→      timeUpdateSub.remove();
   119→      statusSub.remove();
   120→      playingSub.remove();
   121→      try { player.release(); } catch {}
   122→      _mountedCount--;
   123→      console.log('[VideoPlayer] UNMOUNTED totalActive=' + _mountedCount);
   124→    };
   125→  }, []); // eslint-disable-line react-hooks/exhaustive-deps
   126→
   127→  // Pause when swiped away; resume + reset thumbnail gate on swipe-back.
   128→  useEffect(() => {
   129→    try {
   130→      if (isActive) {
   131→        hasCalledOnPlaying.current = false;
   132→        player.play();
   133→      } else {
   134→        player.pause();
   135→      }
   136→    } catch {}
   137→  }, [isActive]); // eslint-disable-line react-hooks/exhaustive-deps
   138→
   139→  return (
   140→    <VideoView
   141→      player={player}
   142→      style={StyleSheet.absoluteFill}
   143→      nativeControls={false}
   144→      contentFit="contain"
   145→    />
   146→  );
   147→}
