     1→/**
     2→ * VideoPlayerView — expo-video player for a single viewer slide.
     3→ *
     4→ * ── WHY THIS COMPONENT EXISTS ────────────────────────────────────────────────
     5→ * key={displayUri} in the parent forces a completely fresh player (and fresh
     6→ * useVideoPlayer hook) for every new file:// URI.  That avoids stale-player
     7→ * state across slides.
     8→ *
     9→ * ── PLAYBACK STRATEGY ────────────────────────────────────────────────────────
    10→ * p.play() inside useVideoPlayer sets ExoPlayer's playWhenReady=true before
    11→ * the surface attaches.  ExoPlayer holds that flag and starts automatically
    12→ * the moment the SurfaceTexture is ready — no external nudge needed.
    13→ *
    14→ * Previous versions added recovery timers and nudge schedules that called
    15→ * player.play() repeatedly after mount.  Those extra calls interrupted
    16→ * ExoPlayer's internal buffer-fill pipeline, causing the play→freeze→play
    17→ * loop on Android 11+.  Removing them lets ExoPlayer manage its own startup
    18→ * and buffering without JS interference.
    19→ *
    20→ * ── PAUSE DEBOUNCE ───────────────────────────────────────────────────────────
    21→ * isActive can briefly flip false→true within a single React render batch
    22→ * (e.g. when a background setStatuses() call shifts item indices).  Calling
    23→ * player.pause() on a transient false fires even though playback should
    24→ * continue.  A 400 ms debounce absorbs those flickers: real swipe-aways keep
    25→ * isActive=false long enough for the timeout to fire; render-only flickers
    26→ * cancel the timeout before it runs.
    27→ *
    28→ * ── NATIVE CONTROLS ──────────────────────────────────────────────────────────
    29→ * nativeControls={true} delegates the play/pause button, seek bar, and
    30→ * fullscreen toggle to expo-video's built-in Android/iOS player UI.
    31→ *
    32→ * ── THUMBNAIL FADE ───────────────────────────────────────────────────────────
    33→ * timeUpdate fires every 250 ms ONLY when frames are actually advancing to the
    34→ * screen (currentTime > 0).  That is the signal we use to fade the poster
    35→ * thumbnail out.  It is more reliable than playingChange because it confirms
    36→ * real rendering, not just an internal ExoPlayer state flip.
    37→ *
    38→ * ── SWIPE-BACK ───────────────────────────────────────────────────────────────
    39→ * When isActive flips false→true the parent has already reset thumbnailOpacity
    40→ * to 1, so we reset hasCalledOnPlaying so onPlaying() can fire again and fade
    41→ * the thumbnail back out.
    42→ */
    43→import React, { useEffect, useRef, useCallback } from 'react';
    44→import { StyleSheet } from 'react-native';
    45→import { VideoView, useVideoPlayer } from 'expo-video';
    46→
    47→interface VideoPlayerViewProps {
    48→  fileUri: string;
    49→  isActive: boolean;
    50→  onPlaying: () => void;
    51→  onError: (message: string) => void;
    52→}
    53→
    54→// ── Mount counter (module-level) ──────────────────────────────────────────────
    55→// Tracks how many VideoPlayerView instances are alive at once.
    56→// Should always be 1 (the active slide). If you see 2+ the FlatList window
    57→// is mounting too many players simultaneously — that competes for the hardware
    58→// decoder and causes freezes.
    59→let _mountedCount = 0;
    60→
    61→export function VideoPlayerView({
    62→  fileUri,
    63→  isActive,
    64→  onPlaying,
    65→  onError,
    66→}: VideoPlayerViewProps) {
    67→  const isActiveRef = useRef(isActive);
    68→  isActiveRef.current = isActive;
    69→
    70→  const hasCalledOnPlaying = useRef(false);
    71→  // True after the first effect run — prevents calling player.play() twice on
    72→  // mount.  useVideoPlayer initializer already sets playWhenReady=true; a
    73→  // second play() call interrupts ExoPlayer's buffer-fill pipeline.
    74→  const didMountRef = useRef(false);
    75→  // Timer ref for the pause debounce — cleared whenever isActive returns true
    76→  // before the timeout fires, so render-flicker false values never reach pause().
    77→  const pauseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    78→
    79→  // ── URI diagnostic log ────────────────────────────────────────────────────
    80→  const uriType = fileUri.startsWith('file://')
    81→    ? 'FILE'
    82→    : fileUri.startsWith('content://')
    83→    ? 'CONTENT⚠️'
    84→    : 'OTHER⚠️';
    85→  console.log('[VideoPlayer] URI type=' + uriType + ' uri=' + fileUri.slice(0, 100));
    86→
    87→  const player = useVideoPlayer({ uri: fileUri }, (p) => {
    88→    p.loop = true;
    89→    p.muted = false;
    90→    // timeUpdate fires every 250 ms only when frames are advancing.
    91→    p.timeUpdateEventInterval = 0.25;
    92→    // Sets playWhenReady=true — ExoPlayer starts as soon as the surface
    93→    // attaches.  No further play() calls are needed from JS.
    94→    p.play();
    95→  });
    96→
    97→  const confirmPlaying = useCallback(() => {
    98→    if (hasCalledOnPlaying.current) return;
    99→    hasCalledOnPlaying.current = true;
   100→    onPlaying();
   101→  }, [onPlaying]);
   102→
   103→  useEffect(() => {
   104→    // ── Mount log ─────────────────────────────────────────────────────────
   105→    _mountedCount++;
   106→    console.log('[VideoPlayer] MOUNTED totalActive=' + _mountedCount + (
   107→      _mountedCount > 1 ? ' ⚠️ MULTIPLE PLAYERS' : ''
   108→    ));
   109→
   110→    const timeUpdateSub = player.addListener('timeUpdate', (event: any) => {
   111→      if ((event.currentTime ?? 0) > 0) confirmPlaying();
   112→    });
   113→
   114→    const statusSub = player.addListener('statusChange', (event: any) => {
   115→      console.log(
   116→        '[VideoPlayer] statusChange status=' + event.status +
   117→        ' currentTime=' + (player.currentTime?.toFixed(2) ?? '?') +
   118→        ' buffered=' + (player.bufferedPosition?.toFixed(2) ?? '?'),
   119→      );
   120→      if (event.status === 'error') {
   121→        onError(event.error?.message ?? 'Playback error');
   122→      }
   123→    });
   124→
   125→    const playingSub = player.addListener('playingChange', (event: any) => {
   126→      console.log(
   127→        '[VideoPlayer] playingChange isPlaying=' + event.isPlaying +
   128→        ' currentTime=' + (player.currentTime?.toFixed(2) ?? '?'),
   129→      );
   130→    });
   131→
   132→    return () => {
   133→      timeUpdateSub.remove();
   134→      statusSub.remove();
   135→      playingSub.remove();
   136→      if (pauseTimerRef.current) {
   137→        clearTimeout(pauseTimerRef.current);
   138→        pauseTimerRef.current = null;
   139→      }
   140→      try { player.release(); } catch {}
   141→      _mountedCount--;
   142→      console.log('[VideoPlayer] UNMOUNTED totalActive=' + _mountedCount);
   143→    };
   144→  }, []); // eslint-disable-line react-hooks/exhaustive-deps
   145→
   146→  // Pause when swiped away; resume + reset thumbnail gate on swipe-back.
   147→  //
   148→  // Skips the initial mount (useVideoPlayer initializer already called p.play()).
   149→  //
   150→  // Pause is DEBOUNCED — isActive can briefly flip false during a render batch
   151→  // caused by a background setStatuses() call.  Calling pause() immediately on
   152→  // a transient false stops a fully-buffered video for no reason.  A 400 ms
   153→  // delay means:
   154→  //   • Render flicker (false then true within one batch): timer cancelled, no pause.
   155→  //   • Real swipe-away (stays false): timer fires, player pauses cleanly.
   156→  useEffect(() => {
   157→    if (!didMountRef.current) {
   158→      didMountRef.current = true;
   159→      return;
   160→    }
   161→
   162→    if (pauseTimerRef.current) {
   163→      clearTimeout(pauseTimerRef.current);
   164→      pauseTimerRef.current = null;
   165→    }
   166→
   167→    if (isActive) {
   168→      hasCalledOnPlaying.current = false;
   169→      try { player.play(); } catch {}
   170→    } else {
   171→      pauseTimerRef.current = setTimeout(() => {
   172→        pauseTimerRef.current = null;
   173→        if (!isActiveRef.current) {
   174→          try { player.pause(); } catch {}
   175→        }
   176→      }, 400);
   177→    }
   178→  }, [isActive]); // eslint-disable-line react-hooks/exhaustive-deps
   179→
   180→  return (
   181→    <VideoView
   182→      player={player}
   183→      style={StyleSheet.absoluteFill}
   184→      nativeControls={true}
   185→      contentFit="contain"
   186→    />
   187→  );
   188→}
