    52→  muted?: boolean;
    53→  style?: ViewStyle;
    54→  onPlayerReady?: (event: NativeSyntheticEvent<Record<string, never>>) => void;
    55→  onPlayerError?: (event: NativeSyntheticEvent<{ error: string }>) => void;
    56→}
