    59→// hasViewManagerConfig is synchronous and safe to call at module load time.
    60→// Returns false when ExoPlayerPackage is not compiled into the current build.
    61→let NativeExoPlayerView: ReturnType<typeof requireNativeComponent<NativeExoPlayerProps>> | null = null;
    62→
    63→if (Platform.OS === 'android') {
    64→  const nativeAvailable = (() => {
    65→    try {
    66→      return UIManager.hasViewManagerConfig('ExoPlayerView');
    67→    } catch {
    68→      return false;
    69→    }
    70→  })();
    71→
    72→  if (nativeAvailable) {
    73→    try {
    74→      NativeExoPlayerView = requireNativeComponent<NativeExoPlayerProps>('ExoPlayerView');
    75→    } catch {
    76→      NativeExoPlayerView = null;
    77→    }
    78→  }
    79→}
