    83→export interface ExoPlayerViewProps {
    84→  /** Must be a file:// URI — never content://. Copy SAF URIs first. */
    85→  fileUri: string;
    86→  paused?: boolean;
    87→  muted?: boolean;
    88→  style?: ViewStyle;
    89→  onPlayerReady?: () => void;
    90→  onPlayerError?: (error: string) => void;
    91→}
    92→
    93→export function ExoPlayerView({
    94→  fileUri,
    95→  paused = false,
    96→  muted = false,
    97→  style,
    98→  onPlayerReady,
    99→  onPlayerError,
   100→}: ExoPlayerViewProps): React.ReactElement | null {
   101→  if (!NativeExoPlayerView) return null;
   102→
   103→  return React.createElement(NativeExoPlayerView, {
   104→    fileUri,
   105→    paused,
   106→    muted,
   107→    style,
   108→    onPlayerReady: onPlayerReady
   109→      ? (_e: NativeSyntheticEvent<Record<string, never>>) => onPlayerReady()
   110→      : undefined,
   111→    onPlayerError: onPlayerError
   112→      ? (e: NativeSyntheticEvent<{ error: string }>) =>
   113→          onPlayerError(e.nativeEvent?.error ?? 'Playback error')
   114→      : undefined,
   115→  });
   116→}
