   120→ * native UIManager registry AND requireNativeComponent succeeded.
   121→ *
   122→ * Checked at module-load time — safe to use as an initial value for useState
   123→ * without any async work.
   124→ */
   125→export function isAvailable(): boolean {
   126→  return NativeExoPlayerView !== null;
   127→}
