    40→// (MIUI / HyperOS). The file persists across restarts so second-time views
    41→// are instant even if the cache was cleared.
    42→export async function runLayer3(
    43→  sourceUri: string,
    44→  id: string,
    45→  name: string,
    46→  type: 'video' | 'image' = 'video',
    47→): Promise<string | null> {
    48→  try {
    49→    const docDir = FileSystem.documentDirectory;
    50→    if (!docDir) return null;
    51→
    52→    const vcacheDir = `${docDir}vcache/`;
    53→    await FileSystem.makeDirectoryAsync(vcacheDir, { intermediates: true });
    54→
    55→    const destUri = `${vcacheDir}doc_${toSafeId(id)}.${ext(name, type)}`;
    56→
    57→    // Return immediately if already cached
    58→    try {
    59→      const info = await FileSystem.getInfoAsync(destUri);
    60→      if (info.exists && (info as any).size > 0) {
    61→        __DEV__ && console.log(`[Layer3] Cache hit: ${name}`);
    62→        return destUri;
    63→      }
    64→    } catch {}
    65→
    66→    __DEV__ && console.log(`[Layer3] Copying to documentDirectory: ${name}`);
    67→    await FileSystem.copyAsync({ from: sourceUri, to: destUri });
    68→
    69→    const verify = await FileSystem.getInfoAsync(destUri);
    70→    if (verify.exists && (verify as any).size > 0) {
    71→      __DEV__ && console.log(`[Layer3] Copy successful: ${name}`);
    72→      return destUri;
    73→    }
    74→
    75→    try { await FileSystem.deleteAsync(destUri, { idempotent: true }); } catch {}
    76→    return null;
    77→  } catch (e) {
